import React, { useState } from 'react';
import { Star, AlertTriangle, TrendingUp, UserCheck, Search } from 'lucide-react';

const PointsTab = () => {
  const [activeSubTab, setActiveSubTab] = useState('REWARDS');

  const rewardsData = [
    { id: 'CIT-001', name: 'John Doe', points: 1250, rank: 1, status: 'ELITE' },
    { id: 'CIT-042', name: 'Jane Smith', points: 980, rank: 2, status: 'PRO' },
    { id: 'CIT-109', name: 'Mike Ross', points: 850, rank: 3, status: 'ACTIVE' },
  ];

  const penaltiesData = [
    { id: 'VIO-88', citizen: 'Alex P.', reason: 'Illegal Dumping', fine: '$50', date: '2026-03-15' },
    { id: 'VIO-89', citizen: 'Sarah L.', reason: 'Hazardous Waste', fine: '$100', date: '2026-03-19' },
  ];

  return (
    <div className="w-full animate-slot flex flex-col gap-6">
      {/* HEADER CONTROL */}
      <div className="flex justify-between items-center bg-[#47510B] p-6 rounded-[30px] border-b-8 border-[#CAD23C]/30 shadow-xl">
        <div className="flex items-center gap-4">
          <Star className="text-[#CAD23C] animate-spin-slow" size={32} />
          <h2 className="text-2xl font-black italic text-[#FDFAD8] uppercase tracking-tighter">04_POINTS_&_GOVERNANCE</h2>
        </div>
        <div className="flex bg-[#FDFAD8]/10 p-1 rounded-xl border border-[#FDFAD8]/20">
          <button 
            onClick={() => setActiveSubTab('REWARDS')}
            className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${activeSubTab === 'REWARDS' ? 'bg-[#CAD23C] text-[#47510B]' : 'text-[#FDFAD8] hover:bg-[#FDFAD8]/10'}`}
          >
            REWARDS_LDR
          </button>
          <button 
            onClick={() => setActiveSubTab('PENALTIES')}
            className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${activeSubTab === 'PENALTIES' ? 'bg-[#AB1717] text-[#FDFAD8]' : 'text-[#FDFAD8] hover:bg-[#FDFAD8]/10'}`}
          >
            PENALTY_LOG
          </button>
        </div>
      </div>

      {activeSubTab === 'REWARDS' ? (
        <div className="grid grid-cols-1 gap-4">
          {rewardsData.map((cit) => (
            <div key={cit.id} className="bg-white border-[6px] border-[#47510B] p-6 rounded-[30px] flex items-center justify-between shadow-[8px_8px_0_0_#A1AED1]">
              <div className="flex items-center gap-6">
                <div className="bg-[#CAD23C] w-12 h-12 rounded-2xl border-4 border-[#47510B] flex items-center justify-center font-black text-xl text-[#47510B]">
                  #{cit.rank}
                </div>
                <div>
                  <h4 className="font-black text-xl text-[#47510B] italic uppercase leading-none">{cit.name}</h4>
                  <p className="text-[10px] font-bold text-[#AB1717] mt-1 tracking-widest">{cit.id} // STATUS: {cit.status}</p>
                </div>
              </div>
              <div className="text-right">
                <span className="text-3xl font-black text-[#47510B] tracking-tighter">{cit.points}</span>
                <p className="text-[9px] font-black uppercase opacity-40">CREDITS_EARNED</p>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-[40px] overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-[#47510B] text-[#FDFAD8] text-[10px] font-black uppercase">
              <tr>
                <th className="p-5 border-r border-[#FDFAD8]/10 italic">Violation_ID</th>
                <th className="p-5 border-r border-[#FDFAD8]/10 italic">Citizen_Node</th>
                <th className="p-5 border-r border-[#FDFAD8]/10 italic">Breach_Type</th>
                <th className="p-5 text-center italic">Penalty_Fee</th>
              </tr>
            </thead>
            <tbody className="bg-white/95 text-[#47510B] font-bold text-sm italic">
              {penaltiesData.map((pen) => (
                <tr key={pen.id} className="border-b-2 border-[#47510B]/10 hover:bg-[#CAD23C]/10 transition-colors">
                  <td className="p-5 border-r border-[#47510B]/5 font-mono">{pen.id}</td>
                  <td className="p-5 border-r border-[#47510B]/5 uppercase">{pen.citizen}</td>
                  <td className="p-5 border-r border-[#47510B]/5 text-[#AB1717]">{pen.reason.toUpperCase()}</td>
                  <td className="p-5 text-center font-black bg-[#AB1717]/5">{pen.fine}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default PointsTab;
